             backup_text =
               {x|# Night Garden Harvest Ledger #
# Track harvests and streak bonuses #

# ===== DATA TYPES ===== #

# Quality tiers from the moonlit fields #
# Higher quality = higher value multiplier #
type Quality =
+ Bronze      # Common harvest, basic value #
+ Silver      # Good quality, moderate bonus #
+ Gold        # Excellent harvest, high value #
+ Starlight   # Legendary, highest value #
in

# Crops that grow under the night sky #
# Each crop has a base value determined by cropValue #
type Crop =
+ Moonmelon
+ Starfruit
+ Nightshade
+ Glowpumpkin
+ Duskwheat
in

# A single harvest from the garden #
# Combines crop type, quality level, and quantity harvested #
type Harvest = (
crop = Crop,
quality = Quality,
quantity = Int
) in

# The harvest ledger tracks all harvests and bonuses #
# harvests: list of all recorded harvests (newest first) #
# totalValue: cumulative value of all harvests plus claimed bonuses #
# streakBonus: current unclaimed streak bonus #
# lastQuality: quality of the most recent harvest (for streak tracking) #
type Model = (
harvests = [Harvest],
totalValue = Int,
streakBonus = Int,
lastQuality = Quality
) in

# Actions the farmer can take #
type Action =
+ RecordHarvest(Harvest)  # Log a new harvest #
+ ClaimBonus              # Collect accumulated streak bonus #
+ CloseDay                # End the harvest day, reset streaks #
in

# ===== VALUE CALCULATIONS ===== #

let cropValue(c: Crop): Int =
case c
| Moonmelon => 15
| Starfruit => 20
| Nightshade => 20
| Glowpumpkin => 12
| Duskwheat => 10
end
in

let qualityMultiplier(q: Quality): Int =
case q
| Bronze => 1
| Silver => 2
| Gold => 3
| Starlight => 5
end
in

# Calculate the value of a single harvest #
# Formula: baseValue * qualityMultiplier * quantity #
let harvestValue(h: Harvest): Int =
cropValue(h.crop) * qualityMultiplier(h.quality) * h.quantity
in

# ===== LEDGER STATE ===== #

# Initial empty ledger #
# Start of a new harvest day with no recorded harvests #
let init : Model = (
harvests = [],
totalValue = 0,
streakBonus = 0,
lastQuality = Bronze
) in

# ===== CORE LOGIC ===== #

# Process a harvest action and update the ledger #
# This function handles streak detection and bonus calculation #
# A streak continues when consecutive harvests have the same quality #
let processHarvest(ledger: Model, h: Harvest): Model =
# Calculate the base value of this harvest #
let value = harvestValue(h) in
# Check if this is the first harvest (no streak possible) #
let isFirst = length(ledger.harvests) == 0 in
# Prepare to update the lastQuality for next comparison #
let newLast = h.quality in
# Determine if the streak continues #
# Streak continues if not first AND current quality matches previous #
let continues = !isFirst && h.quality == newLast in
# Calculate new streak bonus #
# If streak continues, add 5 to existing bonus #
# If streak breaks, reset to 0 #
let newStreak =
if continues
then ledger.streakBonus + 5
else 0
in
# Return updated ledger #
(
harvests = h :: ledger.harvests,
totalValue = ledger.totalValue + value + newStreak,
streakBonus = newStreak,
lastQuality = newLast
)
in

# Claim the streak bonus and reset it #
# Adds current streak bonus to total, then zeroes streak #
let claimBonus(ledger: Model): Model =
(
harvests = ledger.harvests,
totalValue = ledger.totalValue + ledger.streakBonus,
streakBonus = 0,
lastQuality = ledger.lastQuality
)
in

# Close the harvest day - reset streak tracking #
# Preserves harvests and total, resets streak state #
let closeDay(ledger: Model): Model =
(
harvests = ledger.harvests,
totalValue = ledger.totalValue,
streakBonus = 0,
lastQuality = Bronze
)
in

# ===== ACTION DISPATCH ===== #

# Main update function - dispatch actions #
# Routes each action type to its handler #
let update(ledger: Model, action: Action): Model =
case action
| RecordHarvest(h) => processHarvest(ledger, h)
| ClaimBonus => claimBonus(ledger)
| CloseDay => closeDay(ledger)
end
in

# Run multiple actions in sequence #
# Folds actions left-to-right, threading the ledger through #
let run(ledger: Model, actions: [Action]): Model =
fold_left(actions, fun (l, a) -> update(l, a), ledger)
in

# ===== TESTS ===== #

# Basic harvest recording #
hint "recording harvest adds to total value"
test
let h: Harvest = (crop = Moonmelon, quality = Bronze, quantity = 2) in
let ledger = update(init, RecordHarvest(h)) in
ledger.totalValue == 30
end;

hint "harvest is added to harvests list"
test
let h: Harvest = (crop = Starfruit, quality = Silver, quantity = 1) in
let ledger = update(init, RecordHarvest(h)) in
length(ledger.harvests) == 1
end;

# Quality multiplier tests #
hint "silver quality doubles value"
test
let h: Harvest = (crop = Duskwheat, quality = Silver, quantity = 1) in
let ledger = update(init, RecordHarvest(h)) in
ledger.totalValue == 20
end;

hint "gold quality triples value"
test
let h: Harvest = (crop = Duskwheat, quality = Gold, quantity = 1) in
let ledger = update(init, RecordHarvest(h)) in
ledger.totalValue == 30
end;

hint "starlight quality gives 5x value"
test
let h: Harvest = (crop = Nightshade, quality = Starlight, quantity = 1) in
let ledger = update(init, RecordHarvest(h)) in
ledger.totalValue == 100
end;

# Streak bonus tests #
hint "same quality builds streak"
test
let h1: Harvest = (crop = Moonmelon, quality = Gold, quantity = 1) in
let h2: Harvest = (crop = Starfruit, quality = Gold, quantity = 1) in
let ledger = run(init, [RecordHarvest(h1), RecordHarvest(h2)]) in
ledger.streakBonus == 5
end;

hint "streak bonus accumulates with consecutive same-quality harvests"
test
let h1: Harvest = (crop = Moonmelon, quality = Silver, quantity = 1) in
let h2: Harvest = (crop = Starfruit, quality = Silver, quantity = 1) in
let h3: Harvest = (crop = Nightshade, quality = Silver, quantity = 1) in
let ledger = run(init, [
RecordHarvest(h1),
RecordHarvest(h2),
RecordHarvest(h3)
]) in
ledger.streakBonus == 10
end;

hint "different quality resets streak"
test
let h1: Harvest = (crop = Moonmelon, quality = Bronze, quantity = 1) in
let h2: Harvest = (crop = Starfruit, quality = Gold, quantity = 1) in
let ledger = run(init, [RecordHarvest(h1), RecordHarvest(h2)]) in
ledger.streakBonus == 0
end;

# Claim bonus tests #
hint "claiming bonus adds to total"
test
let h1: Harvest = (crop = Moonmelon, quality = Gold, quantity = 1) in
let h2: Harvest = (crop = Starfruit, quality = Gold, quantity = 1) in
let ledger = run(init, [
RecordHarvest(h1),
RecordHarvest(h2),
ClaimBonus
]) in
ledger.streakBonus == 0
end;

# Close day tests #
hint "closing day resets streak tracking"
test
let h1: Harvest = (crop = Moonmelon, quality = Gold, quantity = 1) in
let h2: Harvest = (crop = Starfruit, quality = Gold, quantity = 1) in
let ledger = run(init, [
RecordHarvest(h1),
RecordHarvest(h2),
CloseDay
]) in
ledger.streakBonus == 0 && ledger.lastQuality == Bronze
end;

# lastQuality tracking tests #
hint "lastQuality tracks most recent harvest quality"
test
let h: Harvest = (crop = Moonmelon, quality = Starlight, quantity = 1) in
let ledger = update(init, RecordHarvest(h)) in
ledger.lastQuality == Starlight
end;

# Crop value tests #
hint "starfruit/nightshade have highest base value"
test
let h1: Harvest = (crop = Nightshade, quality = Bronze, quantity = 1) in
let h2: Harvest = (crop = Moonmelon, quality = Bronze, quantity = 1) in
let ledger1 = update(init, RecordHarvest(h1)) in
let ledger2 = update(init, RecordHarvest(h2)) in
ledger1.totalValue > ledger2.totalValue
end;

